/* ClipCast Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #1868DB;
  --primary-dark: #1457b8;
  --accent: #FF613D;
  --accent-light: #fff0ed;
  --text: #292A2E;
  --text-secondary: #5a5c63;
  --text-muted: #8a8d96;
  --bg: #ffffff;
  --bg-alt: #f7f8fb;
  --bg-purple: #f4f1fe;
  --border: #e5e7eb;
  --radius: 12px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow: 0 4px 12px rgba(0,0,0,0.06);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.08);
  --shadow-xl: 0 24px 48px rgba(0,0,0,0.10);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Navigation */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(12px);
  border-bottom: 1px solid var(--border);
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}
.nav-logo {
  font-weight: 800;
  font-size: 1.25rem;
  color: var(--text);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 8px;
}
.nav-logo .dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: var(--accent);
  display: inline-block;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}
.nav-links a {
  text-decoration: none;
  color: var(--text-secondary);
  font-weight: 500;
  font-size: 0.9375rem;
  transition: color 0.2s;
}
.nav-links a:hover { color: var(--text); }
.nav-cta {
  display: flex;
  align-items: center;
  gap: 16px;
}
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 20px;
  border-radius: 10px;
  font-weight: 600;
  font-size: 0.9375rem;
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  line-height: 1.4;
}
.btn-primary {
  background: var(--primary);
  color: #fff;
}
.btn-primary:hover { background: var(--primary-dark); transform: translateY(-1px); }
.btn-accent {
  background: var(--accent);
  color: #fff;
}
.btn-accent:hover { filter: brightness(0.95); transform: translateY(-1px); }
.btn-outline {
  background: transparent;
  color: var(--text);
  border: 1px solid var(--border);
}
.btn-outline:hover { background: var(--bg-alt); }
.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
}
.btn-ghost:hover { color: var(--text); }
.btn-lg { padding: 14px 28px; font-size: 1rem; border-radius: var(--radius-lg); }
.btn-white {
  background: #fff;
  color: var(--primary);
}
.btn-white:hover { background: #f0f4ff; }

/* Hero */
.hero {
  padding: 80px 0 64px;
  text-align: center;
  background: linear-gradient(180deg, #fff 0%, var(--bg-purple) 100%);
}
.hero h1 {
  font-size: clamp(2.5rem, 5vw, 3.75rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: 20px;
}
.hero p {
  font-size: clamp(1.0625rem, 2vw, 1.25rem);
  color: var(--text-secondary);
  max-width: 640px;
  margin: 0 auto 32px;
}
.hero-btns {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Logo bar */
.logo-bar {
  padding: 32px 0;
  border-bottom: 1px solid var(--border);
}
.logo-bar p {
  text-align: center;
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 20px;
  font-weight: 500;
}
.logo-row {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 40px;
  flex-wrap: wrap;
}
.logo-item {
  font-weight: 700;
  font-size: 1.125rem;
  color: var(--text-muted);
  opacity: 0.7;
}

/* Sections */
.section { padding: 80px 0; }
.section-alt { background: var(--bg-alt); }
.section-purple { background: var(--bg-purple); }
.section-header {
  text-align: center;
  max-width: 720px;
  margin: 0 auto 48px;
}
.section-header h2 {
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}
.section-header p {
  font-size: 1.0625rem;
  color: var(--text-secondary);
}
.badge {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 12px;
}
.badge-accent { background: var(--accent-light); color: var(--accent); }
.badge-purple { background: #ede9fe; color: #7c3aed; }

/* Feature cards */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}
.feature-card {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: box-shadow 0.2s, transform 0.2s;
}
.feature-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.feature-icon {
  width: 44px; height: 44px;
  border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.25rem;
  margin-bottom: 16px;
}
.feature-card h3 {
  font-size: 1.0625rem;
  font-weight: 700;
  margin-bottom: 6px;
}
.feature-card p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
}

/* Two column layouts */
.two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
@media (max-width: 768px) {
  .two-col { grid-template-columns: 1fr; gap: 32px; }
  .nav-links { display: none; }
}

/* Mockup box */
.mockup {
  background: linear-gradient(135deg, #e0e7ff 0%, #c7d2fe 100%);
  border-radius: var(--radius-lg);
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.mockup-inner {
  background: #fff;
  border-radius: var(--radius);
  box-shadow: var(--shadow-xl);
  width: 85%;
  height: 75%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
}

/* Stats */
.stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  text-align: center;
}
.stat-item h3 {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--primary);
  line-height: 1;
}
.stat-item p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  margin-top: 8px;
}

/* Testimonials */
.testimonial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}
.testimonial-card {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
}
.testimonial-card p {
  font-size: 1rem;
  color: var(--text-secondary);
  margin-bottom: 16px;
  line-height: 1.6;
}
.testimonial-card .author {
  font-weight: 700;
  color: var(--text);
  font-size: 0.9375rem;
}
.testimonial-card .role {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* CTA Banner */
.cta-banner {
  padding: 80px 0;
  text-align: center;
  background: linear-gradient(135deg, var(--primary) 0%, #3b82f6 100%);
  color: #fff;
}
.cta-banner h2 {
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 800;
  margin-bottom: 12px;
}
.cta-banner p {
  font-size: 1.0625rem;
  opacity: 0.9;
  margin-bottom: 28px;
}

/* Footer */
.footer {
  background: var(--text);
  color: #a1a4ad;
  padding: 64px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 40px;
  margin-bottom: 48px;
}
.footer-col h4 {
  color: #fff;
  font-size: 0.875rem;
  font-weight: 700;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.footer-col a {
  display: block;
  color: #a1a4ad;
  text-decoration: none;
  font-size: 0.875rem;
  margin-bottom: 10px;
  transition: color 0.2s;
}
.footer-col a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid #3a3c42;
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-brand {
  font-weight: 800;
  color: #fff;
  font-size: 1.125rem;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Pricing */
.pricing-toggle {
  display: inline-flex;
  align-items: center;
  background: var(--bg-alt);
  border-radius: 999px;
  padding: 4px;
  gap: 4px;
  margin-bottom: 24px;
}
.pricing-toggle button {
  padding: 8px 20px;
  border-radius: 999px;
  border: none;
  background: transparent;
  font-weight: 600;
  font-size: 0.9375rem;
  cursor: pointer;
  color: var(--text-secondary);
  transition: all 0.2s;
}
.pricing-toggle button.active {
  background: #fff;
  color: var(--text);
  box-shadow: var(--shadow-sm);
}
.save-badge {
  display: inline-flex;
  align-items: center;
  background: #dcfce7;
  color: #166534;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  margin-left: 8px;
}
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
  align-items: start;
}
.pricing-card {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  position: relative;
  transition: box-shadow 0.2s, transform 0.2s;
}
.pricing-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.pricing-card.popular {
  border-color: var(--primary);
  box-shadow: 0 0 0 1px var(--primary);
}
.popular-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 14px;
  border-radius: 999px;
}
.pricing-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 4px;
}
.pricing-card .price {
  font-size: 2.5rem;
  font-weight: 800;
  line-height: 1;
  margin: 16px 0 8px;
}
.pricing-card .price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-secondary);
}
.pricing-card .price-note {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 20px;
}
.pricing-card ul {
  list-style: none;
  margin-bottom: 24px;
}
.pricing-card ul li {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  padding: 6px 0;
  display: flex;
  align-items: flex-start;
  gap: 8px;
}
.pricing-card ul li::before {
  content: "✓";
  color: var(--primary);
  font-weight: 700;
  flex-shrink: 0;
}

/* Comparison table */
.comparison-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9375rem;
  margin-top: 24px;
}
.comparison-table th,
.comparison-table td {
  padding: 14px 16px;
  text-align: left;
  border-bottom: 1px solid var(--border);
}
.comparison-table th {
  font-weight: 700;
  color: var(--text);
  background: var(--bg-alt);
}
.comparison-table td {
  color: var(--text-secondary);
}
.comparison-table tr:hover td {
  background: var(--bg-alt);
}
.comparison-toggle {
  display: none;
}
.comparison-toggle.open {
  display: table-row;
}

/* FAQ */
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 0;
  background: none;
  border: none;
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  text-align: left;
}
.faq-question .icon {
  transition: transform 0.2s;
  font-size: 1.25rem;
  color: var(--text-muted);
}
.faq-item.open .faq-question .icon {
  transform: rotate(45deg);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-item.open .faq-answer {
  max-height: 400px;
  padding-bottom: 20px;
}
.faq-answer p {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  line-height: 1.7;
}

/* Slider */
.slider-wrap {
  margin: 24px 0;
}
.slider-wrap label {
  display: block;
  font-weight: 600;
  margin-bottom: 8px;
  font-size: 0.9375rem;
}
input[type=range] {
  width: 100%;
  accent-color: var(--primary);
  height: 6px;
}
.slider-value {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-top: 4px;
}

/* Forms */
.form-page {
  min-height: 100vh;
  display: grid;
  grid-template-columns: 1fr 1fr;
}
.form-panel {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 48px;
  max-width: 480px;
  margin: 0 auto;
  width: 100%;
}
.form-panel h1 {
  font-size: 1.75rem;
  font-weight: 800;
  margin-bottom: 24px;
}
.social-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: #fff;
  font-weight: 600;
  font-size: 0.9375rem;
  cursor: pointer;
  margin-bottom: 10px;
  transition: background 0.2s;
}
.social-btn:hover { background: var(--bg-alt); }
.divider {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 20px 0;
  color: var(--text-muted);
  font-size: 0.875rem;
}
.divider::before, .divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--border);
}
.input {
  width: 100%;
  padding: 12px 14px;
  border-radius: 10px;
  border: 1px solid var(--border);
  font-size: 1rem;
  font-family: inherit;
  margin-bottom: 16px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(24,104,219,0.12);
}
.form-footer {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-top: 16px;
  text-align: center;
}
.form-footer a { color: var(--primary); text-decoration: none; }
.form-footer a:hover { text-decoration: underline; }
.sidebar {
  background: linear-gradient(135deg, var(--primary) 0%, #3b82f6 100%);
  color: #fff;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 48px;
}
.sidebar-quote {
  font-size: 1.25rem;
  line-height: 1.6;
  font-weight: 500;
  margin-bottom: 24px;
}
.sidebar-author {
  font-weight: 700;
}
.sidebar-role {
  opacity: 0.8;
  font-size: 0.9375rem;
}
@media (max-width: 768px) {
  .form-page { grid-template-columns: 1fr; }
  .sidebar { display: none; }
}

/* Cookie banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0; right: 0;
  background: #fff;
  border-top: 1px solid var(--border);
  box-shadow: var(--shadow-lg);
  padding: 20px 24px;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}
.cookie-banner p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  flex: 1;
}
.cookie-banner.hidden { display: none; }

/* Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 300;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s;
}
.modal-overlay.open {
  opacity: 1;
  pointer-events: auto;
}
.modal {
  background: #fff;
  border-radius: var(--radius-lg);
  max-width: 480px;
  width: 100%;
  padding: 32px;
  box-shadow: var(--shadow-xl);
  transform: translateY(8px);
  transition: transform 0.2s;
}
.modal-overlay.open .modal {
  transform: translateY(0);
}
.modal h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 8px;
}
.modal p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  margin-bottom: 20px;
}
.toggle-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid var(--border);
}
.toggle-row label {
  font-weight: 600;
  font-size: 0.9375rem;
}
.toggle-row span {
  font-size: 0.875rem;
  color: var(--text-muted);
}
.switch {
  position: relative;
  width: 44px; height: 24px;
}
.switch input { opacity: 0; width: 0; height: 0; }
.switch .slider {
  position: absolute;
  inset: 0;
  background: var(--border);
  border-radius: 999px;
  cursor: pointer;
  transition: background 0.2s;
}
.switch .slider::before {
  content: "";
  position: absolute;
  height: 18px; width: 18px;
  left: 3px; top: 3px;
  background: #fff;
  border-radius: 50%;
  transition: transform 0.2s;
}
.switch input:checked + .slider { background: var(--primary); }
.switch input:checked + .slider::before { transform: translateX(20px); }
.modal-actions {
  display: flex;
  gap: 12px;
  justify-content: flex-end;
  margin-top: 20px;
}

/* Mobile nav */
.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
}
@media (max-width: 768px) {
  .mobile-menu-btn { display: block; }
  .nav-links { display: none; }
}

/* Blog cards */
.blog-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}
.blog-card {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow 0.2s;
}
.blog-card:hover { box-shadow: var(--shadow-lg); }
.blog-thumb {
  height: 160px;
  background: linear-gradient(135deg, #e0e7ff 0%, #c7d2fe 100%);
}
.blog-card .content { padding: 20px; }
.blog-card h3 {
  font-size: 1.0625rem;
  font-weight: 700;
  margin-bottom: 8px;
  line-height: 1.4;
}
.blog-card p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
}

/* Use case cards */
.usecase-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 20px;
}
.usecase-card {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  text-align: center;
  transition: box-shadow 0.2s, transform 0.2s;
}
.usecase-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.usecase-card .emoji {
  font-size: 2.5rem;
  margin-bottom: 12px;
}
.usecase-card h3 {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 6px;
}
.usecase-card p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
}

/* Integrations row */
.integrations-row {
  display: flex;
  justify-content: center;
  gap: 32px;
  flex-wrap: wrap;
  margin-top: 32px;
}
.integration-item {
  width: 64px; height: 64px;
  border-radius: var(--radius);
  background: #fff;
  border: 1px solid var(--border);
  display: flex;
